UPDATE asset_fence_state
SET inside = #{transition.inside}, last_transition_position_ts = #{transition.positionTs},
    fence_version = #{transition.fenceVersion}
WHERE tenant_id = #{transition.tenantId} AND asset_id = #{transition.assetId}
    AND fence_id = #{transition.fenceId}
    AND last_transition_position_ts < #{transition.positionTs}
    AND inside != #{transition.inside}
